import six
from threading import Event, Thread
import six
from abc import ABCMeta, abstractmethod

from ute_common_util.timeout import Timeout


class KillableThread(Thread):

    def __init__(self, *args, **kwargs):
        """Supports same parameters as Thread class."""
        super(KillableThread, self).__init__(*args, **kwargs)
        self.terminated_event = Event()

    def is_terminated(self):
        """Returns True if terminate() was called on this thread, False otherwise. Not to be confused with is_alive()."""
        return self.terminated_event.is_set()

    def is_not_terminated(self):
        """Returns True if terminate() was NOT called on this thread, False otherwise. Not to be confused with is_alive()."""
        return not self.is_terminated()

    def terminate(self):
        """
        Tells this thread to terminate gracefully.
        This method does nothing by itself, but the next time is_terminated() is called, it will return True.
        """
        self.terminated_event.set()

    def terminate_and_join(self, timeout=None):
        """
        Tells this thread to terminate gracefully and waits for it to actually terminate.
        The default timeout is infinite and should be used with care. Returns True on success and False otherwise.
        """
        self.terminate()
        self.join(timeout)
        return not self.is_alive()

    def sleep_unless_terminated(self, time):
        """
        Sleeps for given amount of time (in seconds) and returns True
        unless this thread is terminated, in which case sleeping is interrupted and False is returned.
        """
        return not self.terminated_event.wait(time)


@six.add_metaclass(ABCMeta)
class KillableRepeatingThread(KillableThread):

    def __init__(self, *args, **kwargs):
        """Supports same parameters as Thread class."""
        super(KillableRepeatingThread, self).__init__(*args, **kwargs)

    def run(self):
        """Keeps invoking repeat_until_terminated() until it raises an exception or this thread is terminated."""
        while not self.is_terminated():
            self.repeat_until_terminated()

    @abstractmethod
    def repeat_until_terminated(self):
        """This function will be repeatedly invoked until it raises an exception or this thread is terminated."""


@six.add_metaclass(ABCMeta)
class KillableRepeatingThreadWithDelay(KillableRepeatingThread):

    def __init__(self, delay, *args, **kwargs):
        """Supports same parameters as Thread class."""
        super(KillableRepeatingThreadWithDelay, self).__init__(*args, **kwargs)
        self.delay = delay

    def repeat_until_terminated(self):
        """
        Calls the repeat_until_terminated_with_delay() method with given delay until it raises an exception or this thread is terminated.
        Delays are counted between beginnings of calls, not between the end of a previous call and the beginning of the next one.
        If calls take longer than the specified delay to complete, there will be no additional delay between them.
        """
        delay_timer = Timeout(self.delay)
        self.repeat_until_terminated_with_delay()
        delay_left = delay_timer.time_left()
        self.sleep_unless_terminated(time=delay_left)

    @abstractmethod
    def repeat_until_terminated_with_delay(self):
        """
        This function will be repeatedly invoked until it raises an exception or this thread is terminated.
        If a single invocation takes less than the specified delay, the thread will wait for the remaining time.
        The waiting process will be interrupted if this thread is terminated.
        """
